#!/usr/bin/env bash
#
# A QA wizard walks a developer through every acceptance criterion of one
# feature, one stage at a time: open the page, do the steps, record pass or fail.
# Generated by /speckit.qa.walk from extensions/qa/scripts/qa-wizard.sh.
# Adapted from Matt Pocock's `wizard` skill (github.com/mattpocock/skills), MIT.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-check stages below the marker.
#
# Usage: ./qa-walk.sh [--only US1-2,EC-1] [--no-browser] [--reopen] [--results <path>]
#   --only       walk only these stage ids; other rows in the results file are kept
#   --no-browser print each URL instead of opening it
#   --reopen     open every URL again, even one already opened this run
#   --results    where the markdown results table goes (default: beside this script)

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

ONLY=""
NO_BROWSER="${NO_BROWSER:-}"
REOPEN=""
RESULTS=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    # A bare --only eats the next option as its value, so the filter matches no
    # stage and the walk reports success having checked nothing.
    --only)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--only needs a stage list' >&2; exit 2; }
      ONLY="$2"; shift 2 ;;
    --only=*)     ONLY="${1#*=}"; shift ;;
    --no-browser) NO_BROWSER=1; shift ;;
    --reopen)     REOPEN=1; shift ;;
    --results)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--results needs a path' >&2; exit 2; }
      RESULTS="$2"; shift 2 ;;
    --results=*)  RESULTS="${1#*=}"; shift ;;
    -h|--help)    sed -n '11,15p' "${BASH_SOURCE[0]}"; exit 0 ;;
    *) printf 'unknown option: %s\n' "$1" >&2; exit 2 ;;
  esac
done

# The last entry of BASH_SOURCE is the wizard itself, whether this library was
# copied into it or sourced from beside it, so the results land by the wizard.
_WIZARD="${BASH_SOURCE[$((${#BASH_SOURCE[@]} - 1))]}"
RESULTS="${RESULTS:-$(cd "$(dirname "$_WIZARD")" && pwd)/qa-walk-results.md}"

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
_STAGE_ID=""
_SKIPPING=""      # non-empty while --only excludes the current stage
RECORDS=()        # one tab-separated record per check: id, check, result, note
_SEEN=()          # every stage id this wizard declares, for the --only check
_OPENED=()        # every URL opened this run, so none is opened twice

# _clear wipes the terminal so only the current stage is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# _excluded ID succeeds when --only was given and does not name ID.
_excluded() {
  [[ -n "$ONLY" ]] || return 1
  [[ ",$ONLY," != *",$1,"* ]]
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser. This wizard tells you what to open and what to look\n' "$DIM"
  printf '  for, then records pass, fail or skip for each check. Stop any time with\n'
  printf '  Ctrl-C. Re-run with --only <id,...> to walk only the stages you name.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage ID "Title" clears the screen, announces the stage and shows progress.
# The id is the spec's own (US1-2, EC-1, SC-003) so results trace back to it.
stage() {
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  _STAGE_ID="$1"
  _SEEN+=("$1")
  if _excluded "$1"; then _SKIPPING=1; return 0; fi
  _SKIPPING=""
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$2" "$RESET"
}

# say "..." prints the Given: the state the check starts from.
say()  { [[ -n "$_SKIPPING" ]] || printf '  %s\n' "$1"; }
# step "..." is one action the developer takes: the When.
step() { [[ -n "$_SKIPPING" ]] || printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { [[ -n "$_SKIPPING" ]] || printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { [[ -n "$_SKIPPING" ]] || printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
good() { [[ -n "$_SKIPPING" ]] || printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# open_url URL opens it in the developer's browser, cross-platform incl. WSL.
open_url() {
  [[ -n "$_SKIPPING" ]] && return 0
  local url="$1"
  if [[ -n "$NO_BROWSER" ]]; then
    printf '  %s↗ open%s %s\n' "$GREEN" "$RESET" "$url"; return 0
  fi
  # A walk returns to the same page many times: one wizard opens 5 pages across
  # 35 calls. Opening each time buries the reviewer in duplicate tabs, so a URL
  # already opened this run is named instead. --reopen restores every open.
  if [[ -z "$REOPEN" ]]; then
    local opened=" ${_OPENED[*]-} "
    if [[ "$opened" == *" $url "* ]]; then
      printf '  %s↗ already open%s %s\n' "$DIM" "$RESET" "$url"
      return 0
    fi
  fi
  _OPENED+=("$url")
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the developer to finish the manual part.
pause() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes. Put it before any
# step that changes data.
confirm() {
  [[ -n "$_SKIPPING" ]] && return 1
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# check "expected" states the Then and records pass, fail or skip for the
# current stage. A fail or a skip takes a one-line note.
check() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s✔ Expected:%s %s\n' "$BOLD" "$RESET" "$1"
  local verdict="" reply="" note_text="" colour=""
  while [[ -z "$verdict" ]]; do
    printf '  %s? pass / fail / skip [p/f/s]%s ' "$YELLOW" "$RESET"
    # End of input records a skip, so a piped run never spins.
    if ! read -r reply; then verdict="skip"; break; fi
    case "${reply//[[:space:]]/}" in
      [pP]*) verdict="pass" ;;
      [fF]*) verdict="fail" ;;
      [sS]*) verdict="skip" ;;
    esac
  done
  if [[ "$verdict" != "pass" ]]; then
    printf '  %sNote (what you saw, or why skipped):%s ' "$BOLD" "$RESET"
    read -r note_text || true
  fi
  case "$verdict" in
    pass) colour="$GREEN" ;;
    fail) colour="$RED" ;;
    *)    colour="$YELLOW" ;;
  esac
  printf '  %s%s%s\n' "$colour" "$verdict" "$RESET"
  RECORDS+=("$(printf '%s\t%s\t%s\t%s' "$_STAGE_ID" "$1" "$verdict" "$note_text")")
}

# finish clears, writes the results table and shows the closing summary. On an
# --only run, rows for stages not walked this time are kept from the previous
# file. Exit code is 1 when any check failed.
finish() {
  local rows=() line id record r_id r_check r_result r_note
  local pass=0 fail=0 skip=0

  # An id that names no stage silently filters every stage out, and the walk
  # then reports success having checked nothing. Refuse before the results file
  # is written, so a mistyped id never overwrites the rows of a good run.
  if [[ -n "$ONLY" ]]; then
    # Join under the default IFS, because ${_SEEN[*]} separates on the first
    # character of IFS and the split below needs IFS to be a comma.
    local seen=" ${_SEEN[*]-} "
    local -a missing=()
    local want
    local IFS=,
    for want in $ONLY; do
      [[ "$seen" == *" $want "* ]] || missing+=("$want")
    done
    unset IFS
    if [[ ${#missing[@]} -gt 0 ]]; then
      printf '%s\n' "no stage in this wizard is named: ${missing[*]}" >&2
      exit 2
    fi
  fi

  if [[ -n "$ONLY" && -f "$RESULTS" ]]; then
    while IFS= read -r line; do
      [[ "$line" == '| '* ]] || continue
      id="${line#| }"; id="${id%% |*}"
      [[ "$id" == "Id" || "$id" == "---" ]] && continue
      _excluded "$id" && rows+=("$line")
    done < "$RESULTS"
  fi

  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    rows+=("| $r_id | ${r_check//|/\\|} | $r_result | ${r_note//|/\\|} |")
  done

  for line in ${rows[@]+"${rows[@]}"}; do
    case "$line" in
      *"| pass |"*) pass=$((pass + 1)) ;;
      *"| fail |"*) fail=$((fail + 1)) ;;
      *"| skip |"*) skip=$((skip + 1)) ;;
    esac
  done

  {
    printf '# QA walk results\n\n'
    printf -- '- **Run**: %s\n' "$(date '+%Y-%m-%d %H:%M')"
    printf -- '- **Result**: %s pass, %s fail, %s skip\n\n' "$pass" "$fail" "$skip"
    printf '| Id | Check | Result | Note |\n|---|---|---|---|\n'
    for line in ${rows[@]+"${rows[@]}"}; do printf '%s\n' "$line"; done
  } > "$RESULTS"

  _clear
  printf '\n'
  if [[ "$fail" -gt 0 ]]; then
    printf '%s%s  ✗ %s check(s) failed%s\n' "$BOLD" "$RED" "$fail" "$RESET"
  else
    printf '%s%s  ✓ Walk complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  printf '%s  %s pass, %s fail, %s skip · written to %s%s\n' \
    "$DIM" "$pass" "$fail" "$skip" "$RESULTS" "$RESET"
  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    [[ "$r_result" == "pass" ]] && continue
    printf '  %s- %s %s: %s%s\n' "$DIM" "$r_id" "$r_result" "$r_note" "$RESET"
  done
  printf '\n'
  [[ "$fail" -gt 0 ]] && exit 1
  return 0
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage per check, in the confirmed order.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Every confirm sits in an if: it fails on "no" and on an --only skip, and set -e would end the walk. A declined
# confirm still reaches the stage's check, so the walk records a skip for it.

TOTAL_STAGES=41

BASE_URL="https://localhost:58671"
CREATE_RECIPE_URL="$BASE_URL/recipes/create-recipe"
RECIPES_URL="$BASE_URL/recipes/"
ACCOUNT_URL="$BASE_URL/account"
BACKOFFICE_URL="$BASE_URL/umbraco"
WAITING_URL="$BASE_URL/umbraco/section/content/dashboard/contributions"

START_STAND_IN='cd src/KCC.Web && RecipeImport__StandInReader=true RateLimits__ImportsPerHour=1000 dotnet watch --non-interactive'
START_CEILING_ZERO='cd src/KCC.Web && RecipeImport__StandInReader=true RecipeImport__MonthlyCeilingUsd=0 dotnet watch --non-interactive'
START_RATE_LIMIT='cd src/KCC.Web && RecipeImport__StandInReader=true RateLimits__ImportsPerHour=2 dotnet watch --non-interactive'
START_IMPORT_OFF='cd src/KCC.Web && RecipeImport__StandInReader=false RecipeImport__Model=no-such-model dotnet watch --non-interactive'
START_REAL_TINY_CEILING='cd src/KCC.Web && RecipeImport__StandInReader=false RecipeImport__MonthlyCeilingUsd=0.0001 dotnet watch --non-interactive'
START_REAL='cd src/KCC.Web && RecipeImport__StandInReader=false RateLimits__ImportsPerHour=100 dotnet watch --non-interactive'

NOTE_STAND_IN="Stand-in reader, spends nothing. The site must run with this start command, from the repository root (restart it if it started another way): $START_STAND_IN"
NOTE_REAL="Real reader, spends money. The site must run with this start command, from the repository root (restart it if it started another way, then reload the page): $START_REAL. It needs Anthropic:ApiKey in KCC.Web's user-secrets."
WARN_SPEND="Real reader: this stage spends money on the owner's Anthropic account. A read of up to 3 photos costs from well under US\$0.01 to about US\$0.15 (spec, Recurring cost), and counts against this site's own monthly ceiling."
CONFIRM_SPEND="The owner has approved this spend. Run the read?"
NOTE_NOT_RUN="Nothing was run. Answer s below and say why."
NOTE_NOT_SUBMITTED="Nothing was submitted. Answer s below and say why."
PHONE_APPROVAL="Production reads for real and every read spends money, so get the owner's approval first."

to_imported_review() {
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it so the wizard starts clean (accept the browser's leave prompt if it shows)."
  step "Choose 'From photos', then 'Add photos' and pick one JPEG."
  step "Choose 'Read recipe' and wait for the review (Review & Submit)."
}

to_match_step() {
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it so the wizard starts clean (accept the browser's leave prompt if it shows)."
  step "Choose 'From photos', then 'Add photos' and pick two JPEGs."
  step "Choose 'Read recipe'. The match step opens, proposing the first published recipe in name order."
}

to_add_variant() {
  open_url "$RECIPES_URL"
  step "Open any published recipe and choose 'Add Variant'. The page reads 'Add a Variant for <recipe>'."
}

banner "QA walk: Recipe Import from Photos, Phase 1"

stage "US1-1" "Camera: live view and several photos"
note "$NOTE_STAND_IN"
note "Run it on a copy of your dev database, with the settings on the start command only and never exported. It needs a published recipe: the dev seeder adds 25 (curl -sk -X POST $BASE_URL/api/dev/seed-recipes, README)."
say "Given you are signed in as your own approved member, on a Mac with a camera."
open_url "$CREATE_RECIPE_URL"
step "If the site sends you to the sign-in page, sign in. It returns you to Create Recipe."
step "Choose 'From photos' and allow the camera when the browser asks."
step "A live camera view shows, with a shutter button ('Take photo'). Press it twice."
step "Two tiles join the photo strip and the count reads '2 of 10 photos'. You are still on the same page."
note "After the pull request deploys, repeat this on an iPhone in Safari and an Android phone in Chrome against production. $PHONE_APPROVAL"
check "The page asks for camera access and shows a live camera view with a control to take a photo, and they can take several photos without leaving the page."

stage "US1-2" "Camera refused: the page says so, device photos still work"
note "$NOTE_STAND_IN"
say "Given camera access is refused for this site."
open_url "$CREATE_RECIPE_URL"
step "In your browser's site settings for localhost:58671, block the camera. Then reload Create Recipe."
step "Choose 'From photos'."
step "The camera message shows: 'The camera is blocked. Allow it in your browser settings, or add photos from your device.'"
step "Choose 'Add photos' and pick a photo or a screenshot from your device. A tile joins the strip."
note "A device with no camera shows 'No camera found. Add photos from your device instead.' A Mac with a camera can show only the blocked case."
note "Leave the camera blocked: the later stages add photos from the device."
check "The page says so, and the member can still add photos and screenshots from the device."

stage "SC-009" "No camera: an import completes with device photos"
note "$NOTE_STAND_IN"
say "Given the camera is still blocked from US1-2."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it, then choose 'From photos'. The camera message shows."
step "Choose 'Add photos' and pick one JPEG from your device."
step "Choose 'Read recipe' and wait for the review (Review & Submit)."
step "The review is filled and 'Submit for Review' is available. US1-6 walks the submission."
check "A member with no camera, or who refuses camera access, completes an import with photos added from the device."

stage "EC-11" "Too many photos, and a file that is not a photo"
note "$NOTE_STAND_IN"
say "Given a signed-in member on the photo step of Create Recipe."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it, then choose 'From photos'."
step "Choose 'Add photos' and pick a file that is not a photo, for example a text file renamed to .jpg."
step "The page refuses it: 'The site can't read this file. Save it as a JPEG and try again.' The photo count does not change."
step "Choose 'Add photos' again and add real photos, repeating until the count reads '10 of 10 photos'."
step "Add one more photo."
step "The page refuses the 11th: 'An import holds up to 10 photos.' The count stays at 10."
check "An 11th photo is refused with a message. A file that is not a supported photo is refused with a message."

stage "EC-14" "The member leaves: the page warns first"
note "$NOTE_STAND_IN"
say "Given a signed-in member on Create Recipe."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it. With nothing added, click the logo in the header. The site leaves at once."
step "Go back to Create Recipe, choose 'From photos' and add one photo."
step "Click the logo. The leave confirmation opens: 'Leave this page? You will lose your photos and everything you have not submitted.'"
step "Choose 'Stay' (or press Escape). The dialog closes, the photo is still in the strip and focus is back on the logo."
step "Click the logo again and choose 'Leave'. The site follows the link with no second prompt."
step "Go back to Create Recipe, choose 'From photos', add one photo and reload the page. The browser raises its own leave prompt."
to_add_variant
step "Choose 'From photos' and add one photo, then click the hero's 'Cancel'. The same leave confirmation opens."
note "The footer holds only the copyright line today, so the footer link in quickstart scenario 10 cannot be clicked. Click one if it exists."
note "After the pull request deploys, on both phones: a header link must open the leave confirmation. On the iPhone a reload gives no warning, because iOS Safari has no leave prompt."
check "Leaving or reloading loses it, and the page warns first."

stage "EC-12" "A read fails: the page keeps the photos and offers a retry"
note "$NOTE_STAND_IN"
note "The stand-in cannot fail, so this stage cuts the connection in the browser: DevTools, Network tab, throttling set to Offline (Chrome, Edge or Firefox)."
say "Given a signed-in member on the photo step of Create Recipe with one photo."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it, choose 'From photos' and add one photo."
step "In DevTools, Network tab, set throttling to Offline."
step "Choose 'Read recipe'."
step "The page shows 'The read failed. Try again, or type the recipe in.' The photo is still in the strip, with 'Try again' and 'Type it in' offered."
step "Set throttling back to No throttling and choose 'Try again'. The read runs and the review opens."
check "The page says that the read failed, keeps the photos, and lets the member try again or type the recipe in."

stage "US1-3" "Reading shows progress, then the review opens filled"
note "$NOTE_STAND_IN"
note "The stand-in answers at once, so the progress screen may only flash by. To hold it, add RecipeImport__StandInDelaySeconds=5 to that command, restart and reload."
say "Given a signed-in member with one photo in the import."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it, choose 'From photos' and add one JPEG."
step "Choose 'Read recipe' and watch for the progress screen: 'Reading your recipe…' with a 'Cancel' button."
step "The review opens (Review & Submit). Look at the recipe's name and description, the first variant's name, description, times and servings, the ingredients and the steps."
note "After the pull request deploys, on both phones: photograph a printed recipe and read it. The review must match the page and the screen must stay on during the read. $PHONE_APPROVAL"
check "The page shows progress, and the review screen then opens with the recipe and its first variant filled from the photos."

stage "US1-4" "Prep time carries an estimate mark"
note "$NOTE_STAND_IN"
note "The stand-in's recipe has an estimated prep time, as if the photos printed none."
say "Given a filled review from an import."
to_imported_review
step "On the review, find Prep Time. Its value carries an 'Estimate' mark with a short reason."
step "Choose 'Edit' on the First variant section. On that step the Prep Time field carries the same 'Estimate' mark and reason."
check "Prep time holds an estimate, marked as an estimate on the review and on its step."

stage "US1-5" "An unclear ingredient carries a check mark"
note "$NOTE_STAND_IN"
note "The stand-in marks one ingredient unclear whatever the photo shows. EC-3 and EC-4 use the real reader on hard photos."
say "Given a filled review from an import."
to_imported_review
step "On the review, find the ingredient marked 'Check this', with its reason. It holds the reader's best reading."
step "Choose 'Edit' on the Ingredients section. The same row carries the mark on the step."
check "That ingredient shows the reader's best reading, marked as unclear."

stage "EC-9" "Missing text: the reader writes it and says so"
note "$NOTE_STAND_IN"
note "The stand-in writes its own description. Whether it also writes a variant name is not defined, so judge the description."
say "Given a filled review from an import."
to_imported_review
step "On the review, find the description that carries a 'Written for you' mark, with its reason."
step "Choose 'Edit' on that section. The mark shows on the step too."
check "The reader writes a short one and marks it as written by the reader."

stage "US1-6" "Submitting an import creates the usual pending draft"
note "$NOTE_STAND_IN"
note "Submissions are limited to 5 an hour per client (README). This stage makes one."
say "Given a signed-in member who is about to submit an imported recipe."
note "SC-001, stand-in time: start a stopwatch as you open Create Recipe and stop it at 'Recipe Submitted!' without correcting anything. Write the time down."
to_imported_review
warn "Submit for Review writes an unpublished recipe and its first variant into this site's database. Use a copy of your dev database."
if confirm "Submit the recipe now?"; then
  step "Choose 'Submit for Review'."
  step "The success sheet reads 'Recipe Submitted!' with a 'Back to Recipes' link."
  open_url "$ACCOUNT_URL"
  step "Under 'My Recipes & Variants' the recipe is listed with a 'Pending review' badge."
  open_url "$WAITING_URL"
  step "Needs the owner's backoffice: sign in at /umbraco, then open Content, Contributions, Waiting. The recipe and its first variant are listed as drafts."
else
  note "$NOTE_NOT_SUBMITTED"
fi
check "The site creates an unpublished recipe with its first variant, exactly as a typed recipe does today, and the member's account page lists it as pending review."

stage "US3-1" "Edit opens that section's step with its current values"
note "$NOTE_STAND_IN"
say "Given an imported recipe on its review, in Create Recipe."
to_imported_review
step "Choose 'Edit' on the Recipe section. 'Recipe Basics' opens with the recipe's name and description."
step "Choose 'Back to review', then 'Edit' on the First variant section. 'First Variant' opens with its name, description, times and servings."
step "Choose 'Back to review', then 'Edit' on Ingredients, and again on Instructions. Each opens with the rows the review showed."
note "SC-007 walks Add Variant and typed recipes."
check "That section's step opens with its current values."

stage "US3-2" "Back to review returns with the changes, skipping the steps between"
note "$NOTE_STAND_IN"
say "Given an imported recipe on its review, in Create Recipe."
to_imported_review
step "Choose 'Edit' on the Ingredients section and change a value, for example the first ingredient's quantity."
step "Choose 'Back to review'."
step "The review opens directly with the change shown. The Instructions step never appeared."
check "The review opens with their changes, without passing through the steps in between."

stage "US3-3" "Editing a marked value clears its mark"
note "$NOTE_STAND_IN"
say "Given an imported recipe with marked values on its review."
to_imported_review
step "On the review, note the 'Estimate' mark on Prep Time and the 'Check this' mark on one ingredient."
step "Choose 'Edit' on the First variant section and change the Prep Time value. Its 'Estimate' mark clears on the step."
step "Choose 'Back to review'. Prep Time shows no mark on the review."
step "Choose 'Edit' on the Ingredients section and change the marked ingredient, for example its quantity. Its mark clears on the step."
step "Choose 'Back to review'. That ingredient shows no mark on the review."
check "Its mark clears on the step and on the review."

stage "US3-4" "The import's photos stay open for comparison"
note "$NOTE_STAND_IN"
say "Given an imported recipe, on its review and on each step."
to_imported_review
step "On the review, find the photo strip (labelled 'Photos'). Choose the tile ('View photo'): the photo opens larger."
step "Close it with 'Close' or Escape. Focus returns to the tile."
step "Choose 'Edit' on each section in turn. On Recipe Basics, First Variant, Ingredients and Instructions the strip is there and the photo opens."
step "The strip has no remove button: photos are removed on the photo step only."
check "They can open the import's photos to compare."

stage "US3-5" "Reading again warns that it replaces the edits"
note "$NOTE_STAND_IN"
say "Given an imported recipe with an edited value on its review."
to_imported_review
step "Choose 'Edit' on the Ingredients section, change a value (for example the first ingredient's name) and choose 'Back to review'."
step "Choose 'Change photos'. The photo step opens with 'Back to review' offered."
step "Choose 'Remove photo', then 'Add photos' and pick a different JPEG."
step "Choose 'Read recipe'. A warning shows first: 'Reading again replaces your edits.' with 'Read again' and 'Cancel' buttons."
step "Choose 'Read again'. The review opens filled from the new read, and your earlier edit is gone."
check "The site first warns that the new read replaces their edits, and then fills the review from the new read."

stage "SC-007" "Every review section is one click away, and one click back"
note "$NOTE_STAND_IN"
say "Given a signed-in member and a published recipe. Walk all four combinations."
open_url "$CREATE_RECIPE_URL"
step "Typed, Create Recipe: go to Create Recipe and reload it, choose 'Type it in', and fill the required fields of each step, choosing 'Next', until the review opens."
step "On the review, choose each 'Edit' button in turn. Each opens its step in one click, and 'Back to review' returns to the review in one click."
step "Imported, Create Recipe: reload, choose 'From photos', add one JPEG, choose 'Read recipe', and repeat the Edit and 'Back to review' clicks."
to_add_variant
step "Typed, Add Variant: choose 'Type it in', fill the required fields of each step, choosing 'Next', until the review opens, and repeat the Edit and 'Back to review' clicks."
step "Imported, Add Variant: reload, choose 'From photos', add one JPEG, choose 'Read recipe', and repeat the clicks."
check "From the review, a member reaches any section's step in one action and returns to the review in one action, in both flows, for imported and typed recipes."

stage "US4-1" "Create Recipe proposes an existing recipe before the review"
note "$NOTE_STAND_IN"
note "With two photos the stand-in proposes the first published recipe in name order. It needs published recipes."
say "Given published recipes on the site and two photos in the import on Create Recipe."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it, choose 'From photos' and add two JPEGs."
step "Choose 'Read recipe'."
step "The match step opens before the review: 'Is this a new way to make <recipe>?', naming the first published recipe in name order, with a short reason."
note "After the pull request deploys, on both phones: photograph a published recipe and read it without submitting. $PHONE_APPROVAL"
check "It names that recipe with a short reason before the review opens."

stage "US4-2" "Adding the photos as a variant of the proposed recipe"
note "$NOTE_STAND_IN"
say "Given the match step from US4-1."
to_match_step
step "Choose 'Add as a new variant of <recipe>'. The review opens, titled 'Adding a variant to <recipe>', with the variant's values filled."
warn "Submit for Review writes an unpublished variant into this site's database. Use a copy of your dev database."
if confirm "Submit the variant now?"; then
  step "Choose 'Submit for Review'."
  step "The success sheet reads 'Variant submitted!' with a 'Back to Recipes' link."
  open_url "$WAITING_URL"
  step "Needs the owner's backoffice: sign in at /umbraco, then open Content, Contributions, Waiting. A draft variant is listed under that recipe."
else
  note "$NOTE_NOT_SUBMITTED"
fi
check "The flow continues as adding a variant to that recipe, with the variant's values filled from the photos, and the submission creates an unpublished variant under that recipe."

stage "US4-3" "Adding the photos to another published recipe"
note "$NOTE_STAND_IN"
say "Given the match step from US4-1, and at least two published recipes."
to_match_step
step "Choose 'Add to another recipe' and pick a different published recipe in the 'Recipe' list."
step "The review opens, titled 'Adding a variant to <recipe>', with the recipe you picked."
check "The flow continues as adding a variant to the recipe they picked."

stage "US4-4" "Keeping the photos as a new recipe"
note "$NOTE_STAND_IN"
say "Given the match step from US4-1."
to_match_step
step "Choose 'Keep it as a new recipe'."
step "The review opens as Create Recipe does: the Recipe section holds a name and description, and the first variant, ingredients and steps are filled."
check "The flow continues as Create Recipe with every value filled."

stage "US4-5" "Photos that copy a variant name it as a possible duplicate"
note "$NOTE_STAND_IN"
note "With three photos the stand-in proposes no recipe and copies a published variant's ingredients and steps."
say "Given published recipes that have published variants."
open_url "$CREATE_RECIPE_URL"
step "Go to Create Recipe and reload it, choose 'From photos' and add three JPEGs, then choose 'Read recipe'."
step "No match step shows. The review opens with the notice 'This looks almost the same as <variant>, a variant of <recipe>.'"
step "'Submit for Review' is still available. Do not press it."
to_add_variant
note "Pick a recipe that has a published variant: the stand-in copies its first variant."
step "Choose 'From photos', add three JPEGs and choose 'Read recipe'."
step "The review opens with the same kind of notice, naming a variant of this recipe. 'Submit for Review' is still available."
check "It names that variant as a possible duplicate, and the member can still continue."

stage "US4-6" "An import from Add Variant fills a variant and proposes no recipe"
note "$NOTE_STAND_IN"
note "Two photos make the stand-in propose a recipe on Create Recipe. Here it must not."
say "Given a published recipe and a signed-in member."
to_add_variant
step "Choose 'From photos', add two JPEGs and choose 'Read recipe'."
step "The review opens directly with no match step, holding a variant (name, description, times, servings, ingredients, steps) for the recipe named in the page title."
check "It fills a new variant of that recipe and proposes no other recipe."

stage "EC-15" "The proposed recipe disappears before the member submits"
note "$NOTE_STAND_IN"
warn "This stage unpublishes a published recipe in this site's database, in the owner's backoffice, and the last step publishes it again. Use a copy of your dev database."
if confirm "Unpublish the proposed recipe for this check?"; then
  say "Given a member who accepted the stand-in's proposed recipe on Create Recipe, and the owner's backoffice open in a second tab."
  to_match_step
  step "Note the proposed recipe's name, then choose 'Add as a new variant of <recipe>'. The review opens, titled 'Adding a variant to <recipe>'."
  open_url "$BACKOFFICE_URL"
  step "Needs the owner's backoffice: sign in and unpublish that recipe."
  step "Back on the review, choose 'Submit for Review'."
  step "The error well shows 'That recipe is no longer on the site.'"
  step "Choose 'Change' beside 'Adding a variant to <recipe>' to go back to the match step, then choose 'Keep it as a new recipe'. The review opens as a new recipe."
  step "In the backoffice, publish the recipe again, so the stages that follow find it."
else
  note "$NOTE_NOT_RUN"
fi
check "The submission fails with the existing \"recipe not found\" message, and the member can go back and keep a new recipe instead."

stage "US2-1" "At the ceiling the photo choice is unavailable, typing still works"
note "Stand-in reader with the ceiling at 0, so the month's total has reached it (quickstart scenario 5). Stop the running site, then start it, from the repository root, with: $START_CEILING_ZERO"
say "Given the month's import spend has reached the ceiling, and a signed-in member."
open_url "$CREATE_RECIPE_URL"
step "Reload Create Recipe after the restart."
step "The start step shows the photo choice as unavailable: 'Photo import is resting until <date>. You can still type the recipe in.' The date is the first day of next month, and 'Type it in' is still offered."
step "Choose 'Type it in'. 'Recipe Basics' opens and the typing steps work as before."
to_add_variant
step "The start step shows the same notice, and 'Type it in' opens 'Variant Info'."
check "The photo choice says that it is unavailable until the first day of the next month, and typing the recipe in works as before."

stage "US2-4" "Raising the ceiling makes reads available again"
note "Stand-in reader. Stop the running site, then start it, from the repository root, with the ceiling setting removed and the hourly limit set to 2 (US2-3 uses it next): $START_RATE_LIMIT"
note "The stand-in costs nothing, so a ceiling of 0 stands for 'reached' here, as in quickstart scenario 5. EC-13 and US2-2 reach the ceiling with real spend."
say "Given the ceiling was reached in US2-1, and the owner has raised it by removing the 0 setting (the default is US\$2)."
open_url "$CREATE_RECIPE_URL"
step "Reload Create Recipe after the restart."
step "The start step offers 'From photos' again, with no unavailable notice."
step "Choose 'From photos', add one JPEG and choose 'Read recipe'. The review opens: the read ran."
check "Reads are available again for the rest of the month."

stage "US2-3" "The hourly limit refuses a read and spends nothing"
note "Stand-in reader with the hourly limit at 2. Start command, from the repository root: $START_RATE_LIMIT"
note "'Spends nothing' is not visible on screen: the limiter answers before anything is reserved, and the stand-in costs nothing anyway."
say "Given the limit is 2 reads per client an hour, and the read in US2-4 counted as the first since the site started."
open_url "$CREATE_RECIPE_URL"
step "On the review from US2-4, or after repeating its steps, choose 'Read again'. Reads still under the limit run and return to the review."
step "Choose 'Read again' until a read is refused. The refusal comes on the third read since the site started."
step "The page shows 'Too many attempts. Try again later.'"
check "The site refuses it with its standard \"try again later\" message and spends nothing."

stage "EC-16" "No reading configured: the photo choice does not appear"
note "An id outside the model table turns the import off, even with the key in user-secrets. Stop the running site, then start it, from the repository root, with: $START_IMPORT_OFF"
say "Given a site whose reading account is not configured, and a signed-in member."
open_url "$CREATE_RECIPE_URL"
step "Reload Create Recipe after the restart."
step "The wizard opens on its first typing step, 'Recipe Basics', with no start step and no 'From photos'."
to_add_variant
step "The wizard opens on its first typing step, 'Variant Info', with no 'From photos'."
note "A site that holds the key reads for real: the real-reader stages that follow show it."
check "The photo choice does not appear."

stage "EC-13" "The ceiling is reached during a read: it finishes, the next is refused"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "Real reader with a ceiling of 0.0001, below the cost of any real read. Stop the running site, then start it, from the repository root, with: $START_REAL_TINY_CEILING. It needs Anthropic:ApiKey in KCC.Web's user-secrets."
  say "Given a signed-in member, the real reader, one photo of a printed recipe, and the month's spend below the ceiling."
  open_url "$CREATE_RECIPE_URL"
  step "Reload Create Recipe after the restart, choose 'From photos' and add the photo."
  step "Choose 'Read recipe'. If a match step opens, choose 'Keep it as a new recipe'."
  step "Let the read finish: the review opens. That read costs more than the ceiling, so the ceiling is now reached."
  step "Choose 'Read again' on the review."
  step "The next read is refused. The photo step shows 'Photo import is resting until <date>. You can still type the recipe in.' with the photo kept, 'Read recipe' off and 'Type it in' offered."
else
  note "$NOTE_NOT_RUN"
fi
check "That read finishes, and the next one is refused."

stage "US2-2" "The month's spend survives a restart"
note "Continues from EC-13: its real read is the spend that must survive. Stop the running site, then start it again, from the repository root, with the same command: $START_REAL_TINY_CEILING"
say "Given the site restarted in the middle of the month, with the ceiling still at 0.0001 and EC-13's spend recorded."
open_url "$CREATE_RECIPE_URL"
step "Reload Create Recipe after the restart."
step "The start step still shows the photo choice as unavailable: 'Photo import is resting until <date>.' The month's spend so far counts against the ceiling."
to_add_variant
step "The start step shows the same notice."
check "The month's spend so far still counts against the ceiling."

stage "US1-7" "Photos with no recipe: nothing is filled, the member can go on"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a photo that shows no recipe, for example a wall, a blank page or a street."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe'."
  step "The photo step stays open with the photo kept and the message 'We couldn't read a recipe in these photos. Try a clearer photo, add photos, or type it in.'"
  step "'Add photos' is still there (and 'Take photo' where the camera is allowed), 'Remove photo' removes the photo, and 'Type it in' leads to typing steps that start empty."
else
  note "$NOTE_NOT_RUN"
fi
check "It says that it found no recipe, fills nothing, and lets the member retake photos, add photos, or type the recipe in."

stage "EC-3" "Hard photos: fill what it can, mark the rest"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a hard photo of a recipe: blurred, with glare or a shadow, a curled page, or taken in a dark kitchen."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "Either the review fills what could be read, with 'Check this' marks on what could not, or the photo step shows 'We couldn't read a recipe in these photos. Try a clearer photo, add photos, or type it in.'"
else
  note "$NOTE_NOT_RUN"
fi
check "The reader fills what it can and marks what it cannot read clearly. When it can read nothing useful, it says so and suggests a clearer photo."

stage "EC-4" "Handwriting: uncertain words and numbers are marked unclear"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a photo of a handwritten recipe card."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "Compare the review with the card. Words or numbers that you can hardly read yourself carry a 'Check this' mark with a short reason, on the review and on their step."
else
  note "$NOTE_NOT_RUN"
fi
check "Handwritten cards are in scope. Uncertain words and numbers are marked unclear."

stage "EC-5" "Screenshots: ads, comments and clutter are ignored"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a screenshot of a recipe on a web page, with ads, comments or other clutter around the recipe."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the screenshot."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "The review holds the recipe only: no ad text and no comment appears in the names, descriptions, ingredients or steps."
else
  note "$NOTE_NOT_RUN"
fi
check "Ads, comments and other clutter around a recipe on a web page are ignored."

stage "EC-1" "One recipe across several photos is combined in order"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given photos of one recipe spread over two pages, the ingredients on one and the method on the next."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the method page first, then the ingredients page."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "The review is one recipe: the ingredients from one page and the steps from the other, in the order the recipe itself gives."
else
  note "$NOTE_NOT_RUN"
fi
check "The reader combines them into one recipe in the order the recipe itself gives."

stage "EC-2" "More than one recipe in the photos: the main one, the others named"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a photo that shows two recipes, for example a magazine page with two."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "The review is filled from the recipe that the photo mainly shows."
  step "A message names the other recipe: 'These photos also show: <recipe>. Import each one on its own.'"
else
  note "$NOTE_NOT_RUN"
fi
check "The reader fills the review from the recipe that the photos mainly show and names the others it saw, so the member can import each one separately."

stage "EC-6" "Ingredient groups collapse into one list in printed order"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a photo of a recipe whose ingredients sit in groups with headings, such as 'For the sauce' and 'For the dough'."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "On the review, the Ingredients list is one flat list in printed order: every group's ingredients are there, and no heading appears as an ingredient."
else
  note "$NOTE_NOT_RUN"
fi
check "Headings such as \"For the sauce\" and \"For the dough\" collapse into one ingredient list in printed order."

stage "EC-7" "Amounts: fractions, ranges, to taste, units as printed"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a photo of a recipe with a mixed number such as 1½, a range such as '2 to 3 cloves', 'salt to taste', an item with no amount, and units such as cups or tbsp."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "Choose 'Edit' on the Ingredients section to see each row's quantity and unit."
  step "1½ shows as 1.5."
  step "'2 to 3 cloves' shows 2 cloves with a 'Check this' mark whose reason names the printed range."
  step "'Salt to taste' and the item with no amount show as to taste: 'Eyeball this ingredient' is on and the row has no quantity."
  step "Units are as printed, not converted."
else
  note "$NOTE_NOT_RUN"
fi
check "Fractions and mixed numbers become numbers, so 1½ becomes 1.5. A range such as \"2 to 3 cloves\" keeps its lower number and is marked unclear, with the printed range in the mark. \"Salt to taste\" and items with no amount become to-taste items. Units stay as printed."

stage "EC-8" "Another language: the recipe comes back in English, marked"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given a photo of a recipe printed in a language other than English."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the photo."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "The review is in English, and its text values carry a 'Translated' mark with the reason 'Translated from <language>.'"
else
  note "$NOTE_NOT_RUN"
fi
check "The recipe comes back in English, marked as translated."

stage "EC-10" "A value the wizard would reject is shortened or blanked, and marked"
warn "$WARN_SPEND"
if confirm "$CONFIRM_SPEND"; then
  note "$NOTE_REAL"
  say "Given an image of a recipe whose name is longer than 255 characters, the limit that Create Recipe already enforces. A long title typed in a notes app and captured as a screenshot will do."
  open_url "$CREATE_RECIPE_URL"
  step "Go to Create Recipe and reload it, choose 'From photos' and add the image."
  step "Choose 'Read recipe' and wait. If a match step opens, choose 'Keep it as a new recipe'."
  step "The review shows the name cut to fit, or blank, with a 'Check this' mark and the reason 'Shortened to fit.' or 'Outside the allowed range.'"
  step "A blank required value shows 'Fill this in before you submit.' and 'Submit for Review' stays off until you fill it."
else
  note "$NOTE_NOT_RUN"
fi
check "A filled value that the wizard would reject, such as a name longer than the existing limit, is shortened or left blank and marked unclear."

stage "SC-001" "A typical printed recipe, photo to submitted draft, in under 3 minutes"
warn "$WARN_SPEND"
warn "Submit for Review also writes an unpublished recipe and its first variant into this site's database. Use a copy of your dev database."
if confirm "The owner has approved this spend, and the submission is fine. Run the read and the submission?"; then
  note "$NOTE_REAL"
  say "Given a typical printed recipe of up to 3 photos, a stopwatch, and a signed-in member."
  open_url "$CREATE_RECIPE_URL"
  step "Start the stopwatch as you open Create Recipe."
  step "Choose 'From photos' and add the photos. Choose 'Read recipe'."
  step "Note the time from 'Read recipe' to the filled review. It should match the page and appear within 60 seconds."
  step "If a match step opens, choose 'Keep it as a new recipe'. Choose 'Submit for Review' without correcting anything."
  step "Stop the stopwatch at 'Recipe Submitted!'."
else
  note "$NOTE_NOT_RUN"
fi
note "Write both times down for research.md, Measured results (A22, A24). The results file keeps only pass, fail or skip."
note "Compare with the stand-in time from US1-6. If you skip this stage, put that time in the note."
check "A member who finds nothing to correct turns a typical printed recipe of up to 3 photos into a submitted draft in under 3 minutes."

finish
